import React, { useEffect, useState } from 'react';
import axios from 'axios';

const fallbackCases = [
  {
    client: 'D2C Fashion Brand',
    category: 'E-commerce',
    title: 'AI Support Agent + FAQ Automation',
    description: 'Deployed an AI support layer and automated repetitive customer queries to reduce support queue pressure.',
    result1Number: '62%',
    result1Label: 'Faster first response',
    result2Number: '38%',
    result2Label: 'Lower support workload',
    status: 'live',
    tools: ['Claude AI', 'Zapier', 'Notion']
  },
  {
    client: 'Real Estate Team',
    category: 'Operations',
    title: 'Lead Qualification Workflow',
    description: 'Built automated lead capture and qualification with routing to sales reps based on intent and urgency.',
    result1Number: '2.4x',
    result1Label: 'Qualified leads/week',
    result2Number: '45%',
    result2Label: 'Less manual follow-up',
    status: 'live',
    tools: ['Google Opal', 'Make', 'Google Sheets']
  }
];

const Cases = () => {
  const [cases, setCases] = useState([]);

  useEffect(() => {
    const fetchCases = async () => {
      try {
        const response = await axios.get('/api/cases');
        if (Array.isArray(response.data) && response.data.length > 0) {
          setCases(response.data);
        } else {
          setCases(fallbackCases);
        }
      } catch (error) {
        console.error('Error fetching cases:', error);
        setCases(fallbackCases);
      }
    };

    fetchCases();
  }, []);

  return (
    <div className="pg" id="page-cases">
      <div className="sec">
        <div style={{ textAlign: 'center', maxWidth: '600px', margin: '0 auto 3rem' }}>
          <span className="lbl reveal">Case Studies</span>
          <h1 className="dp reveal d1" style={{ marginTop: '.5rem' }}>
            Real results.<br />
            <span className="gr">Real businesses.</span>
          </h1>
          <p className="blg reveal d2" style={{ marginTop: '.9rem' }}>
            See how we've helped businesses transform their operations with AI.
          </p>
        </div>

        {cases.length > 0 ? (
          <div className="crows">
            {cases.map((caseStudy, index) => (
              <div key={index} className="crow">
                <div className="cl">
                  <div className="ctag">{caseStudy.category}</div>
                  <div className="cclient">{caseStudy.client}</div>
                  <div className={`cstat ${caseStudy.status === 'live' ? 'live' : ''}`}>
                    {caseStudy.status === 'live' ? 'Live' : 'Coming Soon'}
                  </div>
                </div>
                <div className="cr">
                  <div className="ctit">{caseStudy.title}</div>
                  <p className="cdesc">{caseStudy.description}</p>
                  <div className="cnums">
                    <div className="cnum">{caseStudy.result1Number}<span className="cnl">{caseStudy.result1Label}</span></div>
                    <div className="cnum">{caseStudy.result2Number}<span className="cnl">{caseStudy.result2Label}</span></div>
                  </div>
                  <div className="ctools">
                    {Array.isArray(caseStudy.tools) && caseStudy.tools.map((tool, i) => (
                      <span key={i} className="ctool">{tool.trim()}</span>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ textAlign: 'center', padding: '4rem', color: 'var(--s)' }}>
            Loading case studies...
          </div>
        )}
      </div>
    </div>
  );
};

export default Cases;
